def comparison (P Q : ModuleProjectiveResolution A D M) : P.obj ⟶ Q.obj :=
  Classical.choose (moduleProjectiveResolution_comparison A D P.projective Q.projective
    P.π Q.π P.quasiIso Q.quasiIso)

def ordinalCover (x y : Set.Iio a) (n : ℤ) :
    (κ.ord.ToType →₀ R) →ₗ[R] linearSpan source target degree R D value coefficient x y n :=
  (fixedFreeCover_ordinal R D κ a source target degree value coefficient hκ hI x y n).choose

noncomputable def chooseBoundaryLift (p : E ⟶ B) [Fibration p] (e : E _⦋0⦌) {n : ℕ}
    (s : B.PtSimplex (n + 1) (p.app _ e)) : _root_.SerrePositivity.InfinityCategories.Kerodon.KanComplexes.HomotopyGroups.BoundaryLift p e s :=
  Classical.choice (_root_.SerrePositivity.InfinityCategories.Kerodon.KanComplexes.HomotopyGroups.boundaryLift_nonempty p e s)

namespace BoundaryLift


variable {p : E ⟶ B} {e : E _⦋0⦌} {n : ℕ}
  {s : B.PtSimplex (n + 1) (p.app _ e)}

/-- 概要：相対ホーンの持ち上げの最後の面は fiber へ写る。
方針：底の代表の最後の面が基点に定数であることを使う。
規約：全空間側の写像として計算する。
使われ方：Kerodon §3.2.5（Tag 00WD）。fiber への連結射の代表。 -/

/-- 元の全空間と strict weighted nerve を結ぶ、両制限を保持した一つの復元データ。 -/
def underSectionReconstruction [Quasicategory B] [_root_.SerrePositivity.InfinityCategories.Kerodon.TheHomotopyTheoryOfInfinityCategories.LeftAndRightFibrations.LeftFibration p] :
    UnderSectionReconstruction p := Classical.choice (nonempty_underSectionReconstruction p)

def weightedDensityTransformation : WeightedDensityTransformation F :=
  Classical.choice (weightedDensityTransformation_nonempty F)

/-- 元の weighted 全空間をパラメータにした、共同 Hom から元の共同分類への一つの変換。 -/

def weightedTwistedSourceLift [Quasicategory C] : WeightedTwistedSourceLift F :=
  Classical.choice (weightedTwistedSourceLift_nonempty F)

end SerrePositivity.InfinityCategories.Kerodon.LargeInfinityCategories.IndCompletionsOfInfinityCategories

def presheafElementsColimitCocone : _root_.SerrePositivity.InfinityCategories.Kerodon.LimitsAndColimits.LimitsAndColimits.JoinCocone (presheafElementsYonedaDiagram F) :=
  Classical.choose (presheafElementsYonedaDiagram_exists_colimitCone F)

/-- 選択した元の全余錐は余極限。元の前層との比較は密度定理の残り。 -/

def presheafDensityTransformation : PresheafDensityTransformation F :=
  Classical.choice (presheafDensityTransformation_nonempty F)

/-- 全小さい元の圏をパラメータにした、同じ共同 Hom から元の F への自然変換。 -/

/-- 中間対象の因子分解比較の実際の内部ホーン。 -/
def dgModuleTriangleMiddleHorn : (SSet.horn 3 2 : SSet.{max (u + 1) v}) ⟶ _root_.SerrePositivity.InfinityCategories.Project.DerivedCategories.dgModuleNerve R D :=
  Classical.choose (dgModuleTriangleMiddleFaces_compatible R D a m b c t ht).exists_desc

/-- 中間対象の因子分解比較の実際の内部ホーン。 -/
def complexTriangleMiddleHorn : (SSet.horn 3 2 : SSet.{u + 1}) ⟶ _root_.SerrePositivity.InfinityCategories.Kerodon.ExamplesOfInfinityCategories.DifferentialGradedCategories.dgNerve S (Complex S) :=
  Classical.choose (complexTriangleMiddleFaces_compatible a m b c t ht).exists_desc

/-- 元の全図式上に、全ての評価が余極限となる前層圏の実際の余極限全余錐を選ぶ。 -/
def presheafCoherentColimitCone : _root_.SerrePositivity.InfinityCategories.Kerodon.LimitsAndColimits.LimitsAndColimits.JoinCocone r :=
  Classical.choose (presheafCoherentColimitCone_exists r)
